#!/usr/bin/env bash
# © 2026 ISPbandits Dev. All rights reserved. Proprietary software.
set -Eeuo pipefail
umask 077

ENV_FILE=${ISPBD_TLS_ENV:-/etc/ispbandits-dev/tls-source.env}
TLS_ROOT=${ISPBD_TLS_ROOT:-/etc/ispbandits-dev/tls}
SERVICE=${ISPBD_XRAY_SERVICE:-ispbandits-xray.service}
TLS_GROUP=${ISPBD_TLS_GROUP:-xray}

[[ ${EUID} -eq 0 ]] || { echo 'Must run as root.' >&2; exit 2; }
[[ -r "$ENV_FILE" ]] || { echo 'TLS source settings are missing.' >&2; exit 1; }
# This root-owned 0600 file is generated by install.sh from validated paths.
# shellcheck disable=SC1090
source "$ENV_FILE"
: "${TLS_CERT_SOURCE:?Missing certificate source path}"
: "${TLS_KEY_SOURCE:?Missing private key source path}"
: "${TLS_DOMAIN:?Missing TLS domain}"
[[ -f "$TLS_CERT_SOURCE" && -f "$TLS_KEY_SOURCE" ]] || { echo 'TLS source files are unavailable.' >&2; exit 1; }

install -d -o root -g "$TLS_GROUP" -m 0750 "$TLS_ROOT/versions"
TMP=$(mktemp -d "$TLS_ROOT/.incoming.XXXXXX")
cleanup() { [[ -z "${TMP:-}" ]] || rm -rf -- "$TMP"; }
trap cleanup EXIT
install -o root -g "$TLS_GROUP" -m 0644 "$TLS_CERT_SOURCE" "$TMP/fullchain.pem"
install -o root -g "$TLS_GROUP" -m 0640 "$TLS_KEY_SOURCE" "$TMP/privkey.pem"
openssl x509 -in "$TMP/fullchain.pem" -noout -checkhost "$TLS_DOMAIN" >/dev/null
openssl x509 -in "$TMP/fullchain.pem" -noout -checkend 86400 >/dev/null
CERT_PUBLIC=$(openssl x509 -in "$TMP/fullchain.pem" -noout -pubkey | openssl pkey -pubin -outform DER | sha256sum | awk '{print $1}')
KEY_PUBLIC=$(openssl pkey -passin pass: -in "$TMP/privkey.pem" -pubout -outform DER | sha256sum | awk '{print $1}')
[[ "$CERT_PUBLIC" == "$KEY_PUBLIC" ]] || { echo 'TLS certificate and private key do not match.' >&2; exit 1; }
VERSION=$(cat "$TMP/fullchain.pem" "$TMP/privkey.pem" | sha256sum | awk '{print $1}')
TARGET="$TLS_ROOT/versions/$VERSION"
if [[ ! -d "$TARGET" ]]; then
  chown root:"$TLS_GROUP" "$TMP"
  chmod 0750 "$TMP"
  mv -- "$TMP" "$TARGET"
  TMP=''
else
  rm -rf -- "$TMP"
  TMP=''
fi

CURRENT=$(readlink -f "$TLS_ROOT/current" 2>/dev/null || true)
if [[ "$CURRENT" != "$TARGET" ]]; then
  LINK="$TLS_ROOT/.current.$$"
  ln -s "$TARGET" "$LINK"
  mv -Tf -- "$LINK" "$TLS_ROOT/current"
  if systemctl is-active --quiet "$SERVICE"; then
    systemctl restart "$SERVICE"
  fi
fi
